import {extractPdfDocument} from './imports.mjs';
import {renderBlocks,renderMarkdown,renderPlainText} from './formatting.mjs';
import {mergeSeedRecords} from './pdf-structure.mjs';
import {TOPICS,KINDS,escapeHtml as esc,matches,matchingPage,snippet,highlight,sortEntries,validateRecord,validateBackup,markdownBrief} from './core.mjs';
import {readState,mutateState} from './db.mjs';
const $=s=>document.querySelector(s);
const icons={library:'<path d="M4 3h5v18H4zM11 3h4v18h-4zM17 4l3-1 4 17-3 1z"/>',notes:'<path d="M5 3h11l4 4v14H5zM15 3v5h5M9 12h7M9 16h7"/>',meeting:'<path d="M5 5h14v16H5zM8 2v6M16 2v6M5 10h14M9 14h6M9 17h4"/>',pin:'<path d="m9 3 6 0-1 6 4 4v2h-5v6l-1 2-1-2v-6H6v-2l4-4z"/>'};
const icon=name=>`<svg viewBox="0 0 26 26" aria-hidden="true">${icons[name]}</svg>`;
let base=[],state={records:[],meeting:[],hidden:[]},selected='',view='library',topic='',kind='',query='',mode='topic',editing=false,dirty=false,editRecord=null,saveTail=Promise.resolve(),noticeTimer,activeBlobUrl;
const workspaceChannel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('mte-scudo-research-desk'):null;
if(workspaceChannel)workspaceChannel.onmessage=async()=>{state=await readState();renderNav();renderList();if(!editing)renderReader();};
const localDate=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const dateLabel=d=>d ? new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(d+'T12:00:00Z')) : 'Undated';
function allRecords(){return mergeSeedRecords(base,state.records);}
function records(){return allRecords().filter(r=>!state.hidden.includes(r.id));}
function getRecord(id){return allRecords().find(r=>r.id===id);}
function filtered(){let list=records().filter(r=>(view!=='notes'||!r.file&&!r.fileData)&&(view!=='meeting'||state.meeting.includes(r.id))&&matches(r,{query,topic,kind}));return view==='meeting' ? list.sort((a,b)=>state.meeting.indexOf(a.id)-state.meeting.indexOf(b.id)) : sortEntries(list,mode);}
function notify(message,error=false){window.clearTimeout(noticeTimer);$('#notice').textContent=message;$('#notice').className=error?'error':'';$('#notice').hidden=false;noticeTimer=window.setTimeout(()=>$('#notice').hidden=true,error?10000:4500);}
async function commit(change){const task=saveTail.catch(()=>{}).then(async()=>{state=await mutateState(change);workspaceChannel?.postMessage('changed');renderNav();renderList();});saveTail=task;try{await task;return true;}catch(e){notify('Could not save. Your changes have not been stored. Export a backup or free browser storage and try again.',true);console.error(e);return false;}}
function renderNav(){const list=records();$('#views').innerHTML=[['library','library','Library',list.length],['notes','notes','My notes',list.filter(r=>!r.file&&!r.fileData).length],['meeting','meeting','Meeting shortlist',state.meeting.filter(id=>list.some(r=>r.id===id)).length]].map(([id,glyph,label,n])=>`<button class="nav-button ${view===id&&!topic?'active':''}" data-view="${id}" ${view===id&&!topic?'aria-current="page"':''}>${icon(glyph)}<span>${label}</span><span class="count">${n}</span></button>`).join('')+'<button class="nav-button backup-mobile" data-backup title="Export or restore your workspace">Backups</button>';
const topics=[...new Set([...TOPICS,...list.flatMap(r=>r.topics)])];$('#topics').innerHTML=topics.filter(t=>t!=='Unsorted'||list.some(r=>r.topics.includes(t))).map(t=>`<button class="nav-button ${topic===t?'active':''}" data-topic="${esc(t)}" ${topic===t?'aria-current="page"':''}><span class="topic-dot"></span><span>${esc(t)}</span><span class="count">${list.filter(r=>r.topics.includes(t)).length}</span></button>`).join('');
$('#view-title').textContent=topic || ({library:'Library',notes:'My notes',meeting:'Meeting shortlist'})[view];$('#view-description').textContent=view==='meeting'?'Keep the sources, questions, and notes you want at hand.':view==='notes'?'Your observations, questions, and working ideas.':topic?`Research filed under ${topic}.`:'Follow a thread. Find your source. Pick up where you left off.';$('#export-brief').hidden=view!=='meeting';$('.segmented').hidden=view==='meeting';
const options=[...new Set([...KINDS,...list.map(r=>r.kind)])];$('#kind').innerHTML='<option value="">All types</option>'+options.filter(k=>list.some(r=>r.kind===k)).map(k=>`<option ${kind===k?'selected':''}>${esc(k)}</option>`).join('');
}
function renderList(){const list=filtered();$('#result-count').textContent=`${list.length} ${list.length===1?'entry':'entries'}${query?' found':''}`;$('#by-topic').setAttribute('aria-pressed',mode==='topic');$('#by-date').setAttribute('aria-pressed',mode==='date');if(!list.length){$('#entries').innerHTML=`<div class="empty"><h3>${view==='meeting'?'Your next meeting starts here.':view==='notes'&&!query&&!topic&&!kind?'Make room for your next idea.':'No matching research.'}</h3><p>${view==='meeting'?'Use the bookmark on any entry to add it to this shortlist.':view==='notes'&&!query&&!topic&&!kind?'Add a note or import a text file. Your original PDFs are in the library.':'Try a different phrase or clear your filters.'}</p>${query||topic||kind?'<button class="button secondary" data-clear>Clear filters</button>':''}${view==='notes'&&!query&&!topic&&!kind?'<button class="button primary" data-new>New note</button>':''}</div>`;return;}
let last='';$('#entries').innerHTML=list.map(r=>{const group=view==='meeting'?'Saved for discussion':mode==='date'?dateLabel(r.date):topic||r.topics[0];const heading=group!==last?`<div class="entry-group">${esc(group)}</div>`:'';last=group;return heading+`<div class="entry ${selected===r.id?'selected':''}"><button class="entry-select" data-id="${r.id}" ${selected===r.id?'aria-current="true"':''}><span class="entry-meta">${esc(r.kind)}<span aria-hidden="true">·</span>${dateLabel(r.date)}${r.pages?`<span aria-hidden="true">·</span>${r.pages.length} pages`:''}</span><span class="entry-title">${highlight(r.title,query)}</span><span class="entry-summary">${highlight(snippet(r,query),query)}</span><span class="entry-topic">${esc(r.topics.join(' / '))}${query&&matchingPage(r,query)>=0?` · Match on page ${matchingPage(r,query)+1}`:''}</span></button><button class="pin" data-pin="${r.id}" aria-label="${state.meeting.includes(r.id)?'Remove from':'Add to'} meeting shortlist: ${esc(r.title)}" aria-pressed="${state.meeting.includes(r.id)}">${icon('pin')}</button></div>`;}).join('');}
const formattingJobs=new Set();
async function formatSavedPdf(r){
  if(!r.fileData||r.pageBlocks||formattingJobs.has(r.id))return;
  formattingJobs.add(r.id);
  try{
    const pdfjs=await import('./vendor/pdf.mjs');
    pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
    const bytes=Uint8Array.from(atob(r.fileData.split(',')[1]),c=>c.charCodeAt(0));
    const formatted=await extractPdfDocument(bytes.buffer,options=>pdfjs.getDocument(options));
    if(await commit(next=>{const stored=next.records.find(x=>x.id===r.id);if(stored)stored.pageBlocks=formatted.pageBlocks;})){
      if(selected===r.id&&!editing){const scroll=$('#reader').scrollTop;renderReader();$('#reader').scrollTop=scroll;}
    }
  }catch(e){console.error('PDF formatting could not be restored',e);}
}
function renderReader(){if(editing)return;const r=getRecord(selected);if(!r||state.hidden.includes(r.id)){$('#reader').innerHTML='<div class="reader-empty">Select an entry to read your research.</div>';return;}if(activeBlobUrl){URL.revokeObjectURL(activeBlobUrl);activeBlobUrl=null;}
formatSavedPdf(r);
let href=r.file;
if(r.fileData){const bytes=Uint8Array.from(atob(r.fileData.split(',')[1]),c=>c.charCodeAt(0));activeBlobUrl=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));href=activeBlobUrl;}
const related=records().filter(x=>x.parentId===r.id);const parent=r.parentId?getRecord(r.parentId):null;
$('#reader').innerHTML=`<div class="reader-content"><div class="reader-bar"><span>${esc(r.kind)} · ${dateLabel(r.date)}</span><div class="reader-actions"><button class="quiet mobile-back" data-back>Back to entries</button>${href?'<button class="quiet" data-edit>Edit details</button><button class="quiet" data-annotate>Add a related note</button>':'<button class="quiet" data-edit>Edit note</button>'}<button class="quiet" data-reader-pin>${state.meeting.includes(r.id)?'Saved for meeting':'Save for meeting'}</button></div></div><h2>${highlight(r.title,query)}</h2><div class="tags">${r.topics.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${r.summary?`<p class="reader-summary">${highlight(r.summary,query)}</p>`:''}${href?`<div class="source-box"><a href="${href}" target="_blank" rel="noopener">Open original PDF ↗</a><p>${esc(r.sourceName||r.title)} · ${r.pages?.length||0} pages</p><p>Source notes, preserved as written. ${esc(r.dateBasis||'The research date has not been set.')}</p></div>`:parent?`<div class="source-box">Related to <button class="quiet" data-id="${esc(parent.id)}">${esc(parent.title)}</button></div>`:''}${r.body?`<div class="note-body rich-text">${renderMarkdown(r.body,query)}</div>`:''}${(r.pages||[]).map((text,i)=>`<details class="page" ${i===(matchingPage(r,query)>=0?matchingPage(r,query):0)?'open':''}><summary>Page ${i+1}${query&&text.toLocaleLowerCase().includes(query.toLocaleLowerCase())?' · Search match':''}</summary>${href?`<div class="page-actions"><a href="${href}#page=${i+1}" target="_blank" rel="noopener" aria-label="Open original PDF on page ${i+1}">Open original page ↗</a></div>`:''}<div class="page-text rich-text">${r.pageBlocks?.[i]?.length?renderBlocks(r.pageBlocks[i],query):renderPlainText(text,query)}</div></details>`).join('')}${related.length?`<section class="related"><h3>Related notes</h3>${related.map(x=>`<button data-id="${x.id}">${esc(x.title)}</button>`).join('')}</section>`:''}<div class="reader-footer"><span class="editor-help">${r.updatedAt?`Edited ${new Date(r.updatedAt).toLocaleDateString()}`:r.seed?'From your research files':'Saved in this browser'}</span><button class="quiet" data-remove>Remove entry</button></div></div>`;
$('#reader').scrollTop=0;}
function canLeave(){if(editing&&dirty&&!window.confirm('Discard the changes to this note?'))return false;editing=false;dirty=false;return true;}
function select(id,mobile=true){if(!canLeave())return;selected=id;history.replaceState(null,'',`#entry=${encodeURIComponent(id)}`);renderList();renderReader();if(mobile){$('.app').classList.add('reading');$('#reader').focus({preventScroll:true});}}
function refresh(){renderNav();renderList();renderReader();if(selected)history.replaceState(null,'',`#entry=${encodeURIComponent(selected)}`);}
function showEditor(r=null,parentId=''){if(!canLeave())return;editing=true;editRecord=r;const note=r||{title:'',date:localDate(),kind:'Note',topics:parentId?getRecord(parentId).topics:[topic||'Unsorted'],summary:'',body:'',parentId};$('#reader').innerHTML=`<form class="editor reader-content" id="note-form"><div class="reader-bar"><span>${r?'Edit note':'New note'}</span><button type="button" class="quiet" data-cancel>Cancel</button></div><h2>${r?'Keep thinking.':'Capture a thought.'}</h2><p class="editor-help">Notes are saved in this browser. Export a backup to keep a portable copy.</p><label for="note-title">Title</label><input id="note-title" name="title" maxlength="500" required value="${esc(note.title)}" placeholder="A question, observation, or idea…"><div class="editor-row"><div><label for="note-date">Research date</label><input id="note-date" name="date" type="date" value="${esc(note.date)}"><span class="editor-help">Leave blank when unknown.</span></div><div><label for="note-kind">Type</label><select id="note-kind" name="kind">${KINDS.map(k=>`<option ${k===note.kind?'selected':''}>${k}</option>`).join('')}</select></div></div><fieldset class="topic-fieldset"><legend>Topics</legend><div class="topic-picker">${[...new Set([...TOPICS,...note.topics])].map(t=>`<label><input type="checkbox" name="topics" value="${esc(t)}" ${note.topics.includes(t)?'checked':''}>${esc(t)}</label>`).join('')}</div></fieldset><label for="note-summary">Short summary <span class="editor-help">(optional)</span></label><textarea class="summary-input" id="note-summary" name="summary" maxlength="2000" rows="2" placeholder="The key point for your future self">${esc(note.summary)}</textarea><label for="note-body">Note</label><textarea id="note-body" name="body" maxlength="2000000" rows="12" placeholder="Write or paste your research here. Markdown supports # headings, **bold**, lists, links, tables, and code blocks.">${esc(note.body)}</textarea><div class="form-actions"><button type="button" class="button secondary" data-cancel>Cancel</button><button class="button primary" id="save-note">Save note</button></div></form>`;$('.app').classList.add('reading');$('#reader').scrollTop=0;$('#note-title').focus();$('#note-form').addEventListener('input',()=>dirty=true);$('#note-form').addEventListener('change',e=>{if(e.target.name==='topics'&&e.target.checked){document.querySelectorAll('[name=topics]').forEach(c=>{if(c!==e.target&&(e.target.value==='Unsorted'||c.value==='Unsorted'))c.checked=false;});}});$('#note-form').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget);const record={...(editRecord||{}),id:editRecord?.id||'note-'+crypto.randomUUID(),title:form.get('title').trim(),date:form.get('date'),kind:form.get('kind'),topics:form.getAll('topics'),summary:form.get('summary').trim(),body:form.get('body'),parentId:note.parentId||'',updatedAt:new Date().toISOString()};if(!record.topics.length)record.topics=['Unsorted'];try{validateRecord(record);}catch(e){notify(e.message,true);return;}$('#save-note').disabled=true;if(await commit(next=>{next.records=next.records.filter(r=>r.id!==record.id).concat(record);})){editing=false;dirty=false;view=record.file||record.fileData?'library':'notes';topic='';kind='';query='';$('#search').value='';selected=record.id;history.replaceState(null,'',`#entry=${record.id}`);refresh();notify('Note saved in this browser.');}else $('#save-note').disabled=false;});}
async function pin(id){await commit(next=>{next.meeting=next.meeting.includes(id)?next.meeting.filter(x=>x!==id):[...next.meeting,id];});if(!editing)renderReader();}
async function remove(){const id=selected;$('#confirm-title').textContent=`Remove “${getRecord(id).title}”?`;$('#confirm-dialog').showModal();$('#confirm-dialog').onclose=async()=>{if($('#confirm-dialog').returnValue!=='remove')return;if(await commit(next=>{next.hidden=[...new Set([...next.hidden,id])];next.meeting=next.meeting.filter(x=>x!==id);})){selected=filtered()[0]?.id||'';renderList();renderReader();notify('Entry removed from this workspace.');}};}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function blobData(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob);});}
async function exportBackup(){await saveTail.catch(()=>{});const button=$('#backup');button.disabled=true;notify('Preparing your backup, including original PDFs…');try{const snapshot=structuredClone(state);const exported=structuredClone(allRecords());for(const r of exported){if(r.file&&!r.fileData){const response=await fetch(r.file);if(!response.ok)throw new Error('Could not include an original PDF.');r.fileData=await blobData(new Blob([await response.arrayBuffer()],{type:'application/pdf'}));}}download(`research-desk-backup-${localDate()}.json`,JSON.stringify({format:'research-desk',version:1,exportedAt:new Date().toISOString(),records:exported,meeting:snapshot.meeting,hidden:snapshot.hidden},null,2),'application/json');notify('Backup downloaded with notes, meeting selections, and original PDFs.');}catch(e){notify('Backup failed: '+e.message,true);}finally{button.disabled=false;}}
async function restoreBackup(file){if(!canLeave())return;if(file.size>200*1024*1024){notify('This backup exceeds the 200 MB import limit.',true);return;}try{const incoming=validateBackup(JSON.parse(await file.text()));if(incoming.hidden!==undefined&&(!Array.isArray(incoming.hidden)||incoming.hidden.some(id=>typeof id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(id))))throw new Error('Invalid removed-entry list.');let conflictCopies=0;const ok=await commit(next=>{const map=new Map(next.records.map(r=>[r.id,r]));for(const r of incoming.records){const existing=map.get(r.id);if(existing&&JSON.stringify(existing)!==JSON.stringify(r)&&existing.updatedAt&&r.updatedAt&&existing.updatedAt>r.updatedAt){const copy={...r,id:'restored-'+crypto.randomUUID(),title:r.title+' (restored copy)'};map.set(copy.id,copy);conflictCopies++;}else map.set(r.id,r);}next.records=[...map.values()];const restoredIds=new Set(incoming.records.map(r=>r.id));next.hidden=[...new Set([...next.hidden.filter(id=>!restoredIds.has(id)),...(incoming.hidden||[])])];next.meeting=[...new Set([...next.meeting,...incoming.meeting])].filter(id=>!next.hidden.includes(id));});if(ok){selected=filtered()[0]?.id||'';refresh();notify(`Restored ${incoming.records.length} entries. ${conflictCopies?`${conflictCopies} older edits kept as separate copies.`:'Existing notes were kept.'}`);}}catch(e){notify('Could not restore backup: '+e.message,true);}}
async function importFiles(files){if(!canLeave())return;const button=$('#import');button.disabled=true;const results=[];let failures=0;try{for(const file of files){try{if(file.size>25*1024*1024)throw new Error('File exceeds 25 MB.');const bytes=await file.arrayBuffer();const fingerprint=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(v=>v.toString(16).padStart(2,'0')).join('');if(records().concat(results).some(r=>r.fingerprint===fingerprint)){notify(`${file.name} is already in your library.`);continue;}const common={id:'import-'+crypto.randomUUID(),title:file.name.replace(/\.(pdf|txt|md)$/i,''),topics:[topic||'Unsorted'],date:'',dateBasis:'Imported without an authored date',summary:'',body:'',sourceName:file.name,fingerprint,updatedAt:new Date().toISOString()};if(/\.pdf$/i.test(file.name)){notify(`Reading ${file.name}…`);const pdfjs=await import('./vendor/pdf.mjs');pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;const {pages,pageBlocks}=await extractPdfDocument(bytes,options=>pdfjs.getDocument(options));common.kind='Document';common.pages=pages;common.pageBlocks=pageBlocks;common.fileData=await blobData(new Blob([bytes],{type:'application/pdf'}));common.summary=pages.every(p=>!p.trim())?'Image-only PDF. Open the original to read it; add a related note to make it searchable.':`Imported PDF with ${pages.length} ${pages.length===1?'page':'pages'}. Add a related note to capture the key points.`;}else if(/\.(md|txt)$/i.test(file.name)){common.kind='Note';common.body=new TextDecoder().decode(bytes);common.summary=common.body.replace(/[#*_]/g,'').replace(/\s+/g,' ').slice(0,180);}else throw new Error('Use a PDF, Markdown, or text file.');validateRecord(common);results.push(common);}catch(e){failures++;notify(`Could not import ${file.name}: ${e.message}`,true);}}
if(results.length&&await commit(next=>{next.records.push(...results);})){selected=results[0].id;view='library';kind='';query='';$('#search').value='';refresh();notify(`${results.length} ${results.length===1?'file':'files'} imported.${failures?` ${failures} failed; other files were saved.`:''}`);}}finally{button.disabled=false;}}
function showBackups(){if(!canLeave())return;$('#reader').innerHTML=`<div class="reader-content"><div class="reader-bar"><span>Workspace</span><button class="quiet mobile-back" data-back>Back to entries</button></div><h2>Keep a copy of your work.</h2><p class="reader-summary">Your additions live in this browser, on this device. A backup carries your notes, PDFs, and meeting shortlist to another browser.</p><div class="source-box"><p>Export regularly, especially before clearing browser data. Browsers may remove stored data; private browsing does not keep it after the session ends.</p></div><p><button class="button primary" data-export-backup>Export full backup</button></p><p><button class="button secondary" data-restore-backup>Restore a backup</button></p><p class="editor-help">Restore merges entries with your current library. An older edited note is kept as a separate copy when a newer edit exists. Original research files remain available.</p></div>`;$('.app').classList.add('reading');}
$('#views').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(e.target.closest('[data-backup]')){showBackups();return;}if(!b||!canLeave())return;view=b.dataset.view;topic='';selected=filtered()[0]?.id||'';$('.app').classList.remove('reading');refresh();});
$('#topics').addEventListener('click',e=>{const b=e.target.closest('[data-topic]');if(!b||!canLeave())return;topic=topic===b.dataset.topic?'':b.dataset.topic;view='library';selected=filtered()[0]?.id||'';$('.app').classList.remove('reading');refresh();});
$('#entries').addEventListener('click',e=>{const p=e.target.closest('[data-pin]');const b=e.target.closest('[data-id]');if(p)pin(p.dataset.pin);else if(b)select(b.dataset.id);else if(e.target.closest('[data-new]'))showEditor();else if(e.target.closest('[data-clear]')){topic='';kind='';query='';$('#search').value='';refresh();}});
$('#reader').addEventListener('click',e=>{if(e.target.closest('[data-back]')){if(canLeave()){$('.app').classList.remove('reading');renderReader();}}else if(e.target.closest('[data-edit]'))showEditor(getRecord(selected));else if(e.target.closest('[data-annotate]'))showEditor(null,selected);else if(e.target.closest('[data-cancel]')){if(canLeave())renderReader();}else if(e.target.closest('[data-reader-pin]'))pin(selected);else if(e.target.closest('[data-remove]'))remove();else if(e.target.closest('[data-id]'))select(e.target.closest('[data-id]').dataset.id);else if(e.target.closest('[data-export-backup]'))exportBackup();else if(e.target.closest('[data-restore-backup]'))$('#backup-input').click();});
$('#search').addEventListener('input',e=>{query=e.target.value;renderList();if(!editing){if(!filtered().some(r=>r.id===selected))selected=filtered()[0]?.id||'';renderReader();renderList();}});
$('#kind').addEventListener('change',e=>{if(!canLeave()){e.target.value=kind;return;}kind=e.target.value;selected=filtered()[0]?.id||'';refresh();});
$('#by-topic').onclick=()=>{mode='topic';renderList();};$('#by-date').onclick=()=>{mode='date';renderList();};$('#new-note').onclick=()=>showEditor();$('#backup').onclick=exportBackup;$('#import-backup').onclick=()=>$('#backup-input').click();$('#import').onclick=()=>$('#file-input').click();
$('#file-input').onchange=async e=>{await importFiles([...e.target.files]);e.target.value='';};$('#backup-input').onchange=async e=>{if(e.target.files[0])await restoreBackup(e.target.files[0]);e.target.value='';};
$('#export-brief').onclick=()=>{const list=state.meeting.map(getRecord).filter(r=>r&&!state.hidden.includes(r.id));if(!list.length){notify('Save an entry to your meeting shortlist first.');return;}download(`mte-scudo-meeting-${localDate()}.md`,markdownBrief(list),'text/markdown');notify('Meeting brief downloaded.');};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();$('#search').focus();}});
try{const response=await fetch('./library.json');if(!response.ok)throw new Error('Source library could not be loaded.');base=(await response.json()).map(validateRecord);state=await readState();state.hidden||=[];const deepLink=new URLSearchParams(location.hash.slice(1)).get('entry');selected=deepLink||base.find(r=>r.kind==='Plan')?.id||base[0]?.id;refresh();if(deepLink)$('.app').classList.add('reading');navigator.storage?.persist?.().catch(()=>{});}catch(e){$('#entries').innerHTML='<div class="empty"><h3>The library could not open.</h3><p>Reload this page. If browser storage is blocked, enable storage for this site.</p></div>';notify(e.message,true);console.error(e);}
